    const hide = ['[data-bridge="dragon"]', '[data-bridge="hr"]', '[data-view="tour"]', '[data-view="allTour"]', '[data-view="walk"]', '#tourCaption', '#weatherSel', '#btnWxStorm', '#timeSlider', '#btnMusic', '.specs'];
